public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
    int n = profits.length;
    boolean[] done = new boolean[n];
    for (int t = 0; t < k; t++) {
        int best = -1;
        for (int i = 0; i < n; i++) {
            if (!done[i] && capital[i] <= w) {
                if (best == -1 || profits[i] > profits[best]) {
                    best = i;
                }
            }
        }
        if (best == -1) break;
        done[best] = true;
        w += profits[best];
    }
    return w;
}

